package paths

import "testing"

// winpathVectors pins the win32 path ports against output generated by running
// the real Node implementation (node -e 'path.win32.…') — see step 3.1 notes.
// Every case runs on every OS because the port is pure string code.
func TestWin32NormalizeVectors(t *testing.T) {
	cases := []struct{ in, want string }{
		{`C:\Users\tylinux`, `C:\Users\tylinux`},
		{`c:/users/tylinux`, `c:\users\tylinux`},
		{`C:\Users\tylinux\`, `C:\Users\tylinux\`},
		{`C:\`, `C:\`},
		{`C:`, `C:.`},
		{`C:/`, `C:\`},
		{`\\server\share`, `\\server\share\`},
		{`\\server\share\`, `\\server\share\`},
		{`\\server\share\\x`, `\\server\share\x`},
		{`//server/share/x`, `\\server\share\x`},
		{`\\?\C:\Users`, `\\?\C:\Users`},
		{`\\.\PHYSICALDRIVE0`, `\\.\PHYSICALDRIVE0`},
		{`Program Files`, `Program Files`},
		{`C:\Program Files\Nex`, `C:\Program Files\Nex`},
		{`C:\Program Files (x86)\Nex`, `C:\Program Files (x86)\Nex`},
		{`D:\data`, `D:\data`},
		{`relative\path`, `relative\path`},
		{`..\..\x`, `..\..\x`},
		{`C:\Users\..\Users`, `C:\Users`},
		{`C:\a\\b/./c`, `C:\a\b\c`},
		{`e:\Users\TYLINUX`, `e:\Users\TYLINUX`},
		{`\\Server\Share\x`, `\\Server\Share\x`},
		{`\\server\share\sub\..`, `\\server\share\`},
		{`C:\\Users\\tylinux`, `C:\Users\tylinux`},
		{`x`, `x`},
		{``, `.`},
		{`.`, `.`},
		{`C:\nex`, `C:\nex`},
		{`\\?\UNC\server\share`, `\\?\UNC\server\share`},
		{`C:\Users/tylinux\AppData`, `C:\Users\tylinux\AppData`},
		{`\\server`, `\server`},
		{`\\server\`, `\server\`},
		{` C:\Users `, ` C:\Users `}, // normalize does NOT trim; callers trim first (paths.ts trims before normalize)
	}
	for _, tc := range cases {
		if got := Win32Normalize(tc.in); got != tc.want {
			t.Errorf("Win32Normalize(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
}

func TestWin32ResolveVectors(t *testing.T) {
	// Absolute drive/UNC inputs resolve without touching cwd; that is the shape
	// every data-dir candidate has after NormalizeWindowsComparablePath.
	cases := []struct{ in, want string }{
		{`C:\Users\tylinux`, `C:\Users\tylinux`},
		{`c:\users\tylinux`, `c:\users\tylinux`},
		{`C:\Program Files\Nex`, `C:\Program Files\Nex`},
		{`\\server\share`, `\\server\share\`},
		{`\\server\share\x`, `\\server\share\x`},
		{`\\?\C:\Users`, `\\?\C:\Users`},
		{`\\.\PHYSICALDRIVE0`, `\\.\PHYSICALDRIVE0`},
	}
	for _, tc := range cases {
		if got := Win32Resolve(tc.in, `C:\cwd`); got != tc.want {
			t.Errorf("Win32Resolve(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
	// A relative input falls back to cwd, as path.win32.resolve does.
	if got := Win32Resolve("data", `C:\Users`); got != `C:\Users\data` {
		t.Errorf("Win32Resolve(relative) = %q, want C:\\Users\\data", got)
	}
}

func TestWin32JoinVectors(t *testing.T) {
	cases := []struct {
		parts []string
		want  string
	}{
		{[]string{`C:\Program Files`, `Nex`}, `C:\Program Files\Nex`},
		{[]string{`C:\Program Files\`, `Nex`}, `C:\Program Files\Nex`},
		{[]string{`C:\Program Files`, ``}, `C:\Program Files`},
		{[]string{`C:\local`, `Programs`, `Nex`}, `C:\local\Programs\Nex`},
		{[]string{}, `.`},
	}
	for _, tc := range cases {
		if got := Win32Join(tc.parts...); got != tc.want {
			t.Errorf("Win32Join(%q) = %q, want %q", tc.parts, got, tc.want)
		}
	}
}
